<?php defined('BASEPATH') OR exit('No direct script access allowed');class Canvases extends MY_Controller{private $c;function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('Canvas_model','canvases');}function index(){if($this->input->method(TRUE)==='POST'){$d=$this->body();if(trim($d['title']??'')==='')return $this->fail('VALIDATION_ERROR','Title is required',422);return $this->respond($this->canvases->save(NULL,$this->c['organizationId'],$this->c['sub'],$d),201);}$p=max(1,(int)$this->input->get('page'));$pp=min(100,max(1,(int)($this->input->get('perPage')?:50)));return $this->respond($this->canvases->list_all($this->c['organizationId'],trim((string)$this->input->get('q')),$p,$pp));}function item($id){$m=$this->input->method(TRUE);if($m==='GET')$r=$this->canvases->one($id,$this->c['organizationId']);elseif($m==='DELETE'){$r=$this->canvases->remove($id,$this->c['organizationId']);if($r)return $this->respond(array());}else $r=$this->canvases->save($id,$this->c['organizationId'],$this->c['sub'],$this->body());return $r?$this->respond($r):$this->fail('NOT_FOUND','Canvas not found',404);}function blocks($id){$d=$this->body();if(!in_array($d['type']??'',array('text','sticky','ai','embed','heading','todo'),TRUE))return $this->fail('VALIDATION_ERROR','Invalid block type',422);$r=$this->canvases->block($id,NULL,$this->c['organizationId'],$d);return $r?$this->respond($r,201):$this->fail('NOT_FOUND','Canvas not found',404);}function block($id,$bid){$r=$this->canvases->block($id,$bid,$this->c['organizationId'],$this->body(),$this->input->method(TRUE)==='DELETE');return $r!==NULL?$this->respond($r):$this->fail('NOT_FOUND','Block not found',404);}function connections($id){$d=$this->body();if(empty($d['fromId'])||empty($d['toId'])||$d['fromId']===$d['toId'])return $this->fail('VALIDATION_ERROR','Valid distinct block endpoints required',422);$r=$this->canvases->connection($id,NULL,$this->c['organizationId'],$d);return $r?$this->respond($r,201):$this->fail('VALIDATION_ERROR','Canvas or endpoint block not found',422);}function connection($id,$cid){$r=$this->canvases->connection($id,$cid,$this->c['organizationId']);return $r!==NULL?$this->respond($r):$this->fail('NOT_FOUND','Connection not found',404);}function generate($id,$bid){$d=$this->body();$prompt=trim($d['prompt']??'');if($prompt===''||strlen($prompt)>4000)return $this->fail('VALIDATION_ERROR','Prompt must contain 1–4000 characters',422);if(!$this->canvases->one($id,$this->c['organizationId']))return $this->fail('NOT_FOUND','Canvas not found',404);$this->load->library('Ai_provider');$out=$this->ai_provider->complete(array(array('role'=>'user','content'=>$prompt)),$d['modelId']??NULL);if(!$out['ok'])return $this->fail($out['code'],$out['message'],503);$block=$this->canvases->generated($id,$bid,$this->c['organizationId'],$prompt,$out['content'],$out['model']);if(!$block)return $this->fail('NOT_FOUND','Block not found',404);if(strpos((string)$this->input->get_request_header('Accept'),'text/event-stream')!==FALSE){$events=json_encode(array('delta'=>$out['content']))."

".'data: '.json_encode(array('result'=>$out['content'],'done'=>TRUE))."

";$this->output->set_content_type('text/event-stream')->set_header('Cache-Control: no-cache, no-transform')->set_output('data: '.$events);return;}return $this->respond(array('result'=>$out['content']));}function presence($id){$m=$this->input->method(TRUE);if($m==='POST'){$d=$this->body();$name=trim($d['displayName']??'');if($name==='')return $this->fail('VALIDATION_ERROR','Display name is required',422);$r=$this->canvases->heartbeat($id,$this->c['sub'],$this->c['organizationId'],$name,$d['avatarColor']??NULL);}elseif($m==='DELETE'){$r=$this->canvases->leave($id,$this->c['sub'],$this->c['organizationId']);if($r)return $this->respond(array());}else $r=$this->canvases->presence($id,$this->c['organizationId']);return $r!==NULL?$this->respond($r):$this->fail('NOT_FOUND','Canvas not found',404);}function cursor($id){$d=$this->body();if(!isset($d['x'],$d['y'])||!is_numeric($d['x'])||!is_numeric($d['y']))return $this->fail('VALIDATION_ERROR','Numeric cursor coordinates required',422);$r=$this->canvases->cursor($id,$this->c['sub'],$this->c['organizationId'],trim($d['displayName']??'User'),$d['x'],$d['y']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Canvas not found',404);}function cursors($id){$r=$this->canvases->cursors($id,$this->c['organizationId']);return $r!==NULL?$this->respond($r):$this->fail('NOT_FOUND','Canvas not found',404);}}
